-- Postgres schema 15. Keep tables, columns and constraints equal to the SQLite
-- statements; TestPostgresSchemaMatchesSQLite compares them. One statement per line.
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, os_uid TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS diffs (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, mode TEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT);
CREATE INDEX IF NOT EXISTS diffs_owner_expiry ON diffs(owner_id, kind, expires_at);
CREATE TABLE IF NOT EXISTS diff_versions (id TEXT PRIMARY KEY, diff_id TEXT NOT NULL REFERENCES diffs(id) ON DELETE CASCADE, revision TEXT NOT NULL, manifest TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(diff_id, revision));
CREATE TABLE IF NOT EXISTS diff_files (version_id TEXT NOT NULL REFERENCES diff_versions(id) ON DELETE CASCADE, file_id TEXT NOT NULL, path TEXT NOT NULL, fingerprint TEXT NOT NULL, patch TEXT NOT NULL, patch_digest TEXT NOT NULL, PRIMARY KEY(version_id, file_id));
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, stream_key TEXT NOT NULL, mode TEXT NOT NULL, UNIQUE(owner_id, stream_key, mode));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, review_id TEXT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, version_id TEXT REFERENCES diff_versions(id) ON DELETE SET NULL, file_id TEXT NOT NULL, data TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS comments_review_created ON comments(review_id, created_at);
CREATE TABLE IF NOT EXISTS marks (review_id TEXT NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, file_id TEXT NOT NULL, version_id TEXT REFERENCES diff_versions(id) ON DELETE SET NULL, patch_digest TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(review_id, file_id));
CREATE TABLE IF NOT EXISTS contexts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind='observation'),anchor_diff_id TEXT NOT NULL UNIQUE REFERENCES diffs(id) ON DELETE CASCADE,created_at BIGINT NOT NULL,last_submitted_at BIGINT NOT NULL,submitted_from TEXT);
CREATE INDEX IF NOT EXISTS contexts_owner_order ON contexts(owner_id,last_submitted_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS observation_repositories (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, repository_key TEXT NOT NULL, UNIQUE(owner_id,repository_key));
CREATE TABLE IF NOT EXISTS observations (context_id TEXT PRIMARY KEY REFERENCES contexts(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL, submission_id TEXT NOT NULL, payload_hash TEXT NOT NULL, repository_id TEXT REFERENCES observation_repositories(id), metadata TEXT NOT NULL, stream_key TEXT NOT NULL, UNIQUE(owner_id,source_id,submission_id));
CREATE TABLE IF NOT EXISTS observation_scopes (context_id TEXT NOT NULL REFERENCES observations(context_id) ON DELETE CASCADE, mode TEXT NOT NULL, diff_id TEXT NOT NULL UNIQUE REFERENCES diffs(id) ON DELETE CASCADE, version_id TEXT NOT NULL REFERENCES diff_versions(id) ON DELETE CASCADE, PRIMARY KEY(context_id,mode));
CREATE TABLE IF NOT EXISTS observation_submissions (owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL, submission_id TEXT NOT NULL, context_id TEXT NOT NULL REFERENCES observations(context_id) ON DELETE CASCADE, payload_hash TEXT NOT NULL, metadata TEXT NOT NULL, PRIMARY KEY(owner_id,source_id,submission_id));
CREATE TABLE IF NOT EXISTS observation_stream_heads (owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL, repository_key TEXT NOT NULL, checkout_key TEXT NOT NULL, branch TEXT NOT NULL, comparison_policy TEXT NOT NULL DEFAULT '', context_id TEXT NOT NULL, collected_at BIGINT NOT NULL, arrival_sequence BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(owner_id,source_id,repository_key,checkout_key,branch,comparison_policy));
CREATE TABLE IF NOT EXISTS observation_identities (owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, identity_hash TEXT NOT NULL, context_id TEXT NOT NULL REFERENCES observations(context_id) ON DELETE CASCADE, PRIMARY KEY(owner_id,identity_hash));
CREATE TABLE IF NOT EXISTS observation_commits (context_id TEXT NOT NULL REFERENCES observations(context_id) ON DELETE CASCADE, ordinal BIGINT NOT NULL, oid TEXT NOT NULL, data TEXT NOT NULL, diff_id TEXT UNIQUE REFERENCES diffs(id) ON DELETE SET NULL, version_id TEXT REFERENCES diff_versions(id) ON DELETE SET NULL, file_count BIGINT NOT NULL, additions BIGINT NOT NULL, deletions BIGINT NOT NULL, PRIMARY KEY(context_id,ordinal), UNIQUE(context_id,oid));
CREATE TABLE IF NOT EXISTS observation_commit_ranges (context_id TEXT PRIMARY KEY REFERENCES observations(context_id) ON DELETE CASCADE, total BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS observations_source ON observations(owner_id,source_id);
CREATE INDEX IF NOT EXISTS observations_stream ON observations(owner_id,stream_key);
CREATE INDEX IF NOT EXISTS observations_branch ON observations(owner_id,(metadata::jsonb #>> '{branch}'));
CREATE TABLE IF NOT EXISTS agent_sessions (owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL, harness TEXT NOT NULL, session_id TEXT NOT NULL, name TEXT NOT NULL, named_at BIGINT NOT NULL, PRIMARY KEY(owner_id,source_id,harness,session_id));
CREATE INDEX IF NOT EXISTS agent_sessions_name ON agent_sessions(owner_id,source_id,name);
CREATE TABLE IF NOT EXISTS observation_sessions (context_id TEXT NOT NULL REFERENCES observations(context_id) ON DELETE CASCADE, owner_id TEXT NOT NULL, source_id TEXT NOT NULL, harness TEXT NOT NULL, session_id TEXT NOT NULL, first_observed_at BIGINT NOT NULL, last_observed_at BIGINT NOT NULL, PRIMARY KEY(context_id,source_id,harness,session_id), FOREIGN KEY(owner_id,source_id,harness,session_id) REFERENCES agent_sessions(owner_id,source_id,harness,session_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS observation_sessions_identity ON observation_sessions(owner_id,source_id,harness,session_id,context_id);
CREATE INDEX IF NOT EXISTS observation_submissions_context ON observation_submissions(context_id);
CREATE INDEX IF NOT EXISTS observation_submissions_run ON observation_submissions(owner_id,(metadata::jsonb #>> '{runId}'),context_id);
CREATE TABLE IF NOT EXISTS ingestion_records (sequence BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, source_id TEXT NOT NULL, submission_id TEXT NOT NULL, payload_hash TEXT NOT NULL, context_id TEXT NOT NULL DEFAULT '', UNIQUE(owner_id,source_id,submission_id));
CREATE TABLE IF NOT EXISTS ingestion_jobs (id TEXT PRIMARY KEY, sequence BIGINT NOT NULL UNIQUE REFERENCES ingestion_records(sequence), payload TEXT NOT NULL, state TEXT NOT NULL, attempt BIGINT NOT NULL DEFAULT 0, available_at BIGINT NOT NULL, lease_until BIGINT NOT NULL DEFAULT 0, lease_token TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', context_id TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS ingestion_jobs_ready ON ingestion_jobs(state,available_at,lease_until);
CREATE TABLE IF NOT EXISTS remote_accounts ( user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS browser_sessions ( secret_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES remote_accounts(user_id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS browser_sessions_owner ON browser_sessions(user_id);
CREATE TABLE IF NOT EXISTS identity_tokens ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES remote_accounts(user_id) ON DELETE CASCADE, name TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN ('collector','api')), secret_hash TEXT NOT NULL UNIQUE, created_at BIGINT NOT NULL, last_used_at BIGINT, expires_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS identity_tokens_owner ON identity_tokens(user_id);
CREATE TABLE IF NOT EXISTS admin_account ( singleton BIGINT PRIMARY KEY CHECK(singleton=1), user_id TEXT NOT NULL UNIQUE REFERENCES remote_accounts(user_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_setup ( singleton BIGINT PRIMARY KEY CHECK(singleton=1), token_hash TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS disabled_accounts ( user_id TEXT PRIMARY KEY REFERENCES remote_accounts(user_id) ON DELETE CASCADE, disabled_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS google_identities ( sub TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES remote_accounts(user_id) ON DELETE CASCADE, email TEXT NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS google_identities_email ON google_identities(email);
CREATE TABLE IF NOT EXISTS account_invites ( id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, email TEXT NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, used_at BIGINT, used_by TEXT REFERENCES remote_accounts(user_id) ON DELETE SET NULL, revoked_at BIGINT);
CREATE INDEX IF NOT EXISTS account_invites_email ON account_invites(email);
CREATE TABLE IF NOT EXISTS google_auth_states ( state_hash TEXT PRIMARY KEY, binding_hash TEXT NOT NULL, nonce TEXT NOT NULL, pkce_verifier TEXT NOT NULL, invite_id TEXT REFERENCES account_invites(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS github_oauth_states (state_hash TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS github_connections (owner_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, user_id BIGINT NOT NULL, login TEXT NOT NULL, access_token BYTEA NOT NULL, access_expires_at BIGINT NOT NULL, refresh_token BYTEA NOT NULL, refresh_expires_at BIGINT NOT NULL, status TEXT NOT NULL, connected_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS github_connections_user ON github_connections(user_id);
CREATE TABLE IF NOT EXISTS github_follows (owner_id TEXT NOT NULL REFERENCES github_connections(owner_id) ON DELETE CASCADE, repository_id BIGINT NOT NULL, installation_id BIGINT NOT NULL, full_name TEXT NOT NULL, status TEXT NOT NULL, verified_at BIGINT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(owner_id, repository_id));
CREATE INDEX IF NOT EXISTS github_follows_repository ON github_follows(repository_id, status);
CREATE INDEX IF NOT EXISTS github_follows_installation ON github_follows(installation_id);
CREATE TABLE IF NOT EXISTS github_deliveries (id TEXT PRIMARY KEY, event TEXT NOT NULL, received_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS github_pull_requests (repository_id BIGINT NOT NULL, number BIGINT NOT NULL, installation_id BIGINT NOT NULL, full_name TEXT NOT NULL, generation BIGINT NOT NULL, refreshed_generation BIGINT NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'open', retention_run TEXT NOT NULL DEFAULT '', requested_at BIGINT NOT NULL, lease_token TEXT NOT NULL DEFAULT '', lease_until BIGINT NOT NULL DEFAULT 0, leased_generation BIGINT NOT NULL DEFAULT 0, leased_run TEXT NOT NULL DEFAULT '', leased TEXT NOT NULL DEFAULT '', attempt BIGINT NOT NULL DEFAULT 0, available_at BIGINT NOT NULL DEFAULT 0, detail TEXT NOT NULL DEFAULT '', PRIMARY KEY(repository_id, number));
CREATE INDEX IF NOT EXISTS github_pull_requests_pending ON github_pull_requests(requested_at) WHERE generation>refreshed_generation;
CREATE TABLE IF NOT EXISTS github_pr_heads (repository_id BIGINT NOT NULL, number BIGINT NOT NULL, head_sha TEXT NOT NULL DEFAULT '', opened BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(repository_id, number), FOREIGN KEY(repository_id, number) REFERENCES github_pull_requests(repository_id, number) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS github_follow_mutes (owner_id TEXT NOT NULL, repository_id BIGINT NOT NULL, PRIMARY KEY(owner_id, repository_id), FOREIGN KEY(owner_id, repository_id) REFERENCES github_follows(owner_id, repository_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS push_keys (singleton BIGINT PRIMARY KEY CHECK(singleton=1), public_key TEXT NOT NULL, private_key TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, endpoint TEXT NOT NULL UNIQUE, p256dh TEXT NOT NULL, auth TEXT NOT NULL, label TEXT NOT NULL, created_at BIGINT NOT NULL, last_success_at BIGINT);
CREATE INDEX IF NOT EXISTS push_subscriptions_owner ON push_subscriptions(owner_id, created_at);
CREATE TABLE IF NOT EXISTS push_notifications (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, job_id TEXT NOT NULL REFERENCES ingestion_jobs(id) ON DELETE CASCADE, kind TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','sent','dropped')), attempt BIGINT NOT NULL DEFAULT 0, available_at BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS push_notifications_due ON push_notifications(available_at) WHERE state='pending';
CREATE INDEX IF NOT EXISTS push_notifications_job ON push_notifications(job_id);
CREATE TABLE IF NOT EXISTS push_deliveries (notification_id TEXT NOT NULL REFERENCES push_notifications(id) ON DELETE CASCADE, subscription_id TEXT NOT NULL REFERENCES push_subscriptions(id) ON DELETE CASCADE, state TEXT NOT NULL CHECK(state IN ('accepted','refused')), PRIMARY KEY(notification_id, subscription_id));
CREATE INDEX IF NOT EXISTS push_deliveries_subscription ON push_deliveries(subscription_id);
